}

function LoadingSkeleton() {
  return (
    <div className="space-y-6">
      <MetricCardGrid>
        {[1, 2, 3].map((i) => (
          <Card key={i} className="border border-border">
            <CardContent className="p-6">
              <Skeleton className="h-4 w-20 mb-2" />
              <Skeleton className="h-8 w-24" />
